import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Tabs, Tab, Input, Link, Card, CardBody, CardHeader, user } from "@heroui/react";
import { useFormik } from "formik";

import { ToastContainer, toast } from "react-toastify";
import 'react-toastify/dist/ReactToastify.css';



export default function DiscountedAmountFormModal({ openCounterDiscountDialog, setopenCounterDiscountDialog, counterDiscount, setcounterDiscount }) {
    const formik = useFormik({
        initialValues: {
            counter_discount: counterDiscount,

        },

        validationSchema: Yup.object({
            counter_discount: Yup.number()
                .min(1)
                .max(20)
                .required().label('Customer'),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action
            setcounterDiscount(values.counter_discount)
            setopenCounterDiscountDialog(false)
            toast.error("20 pc")


        },
    });


    useEffect(() => { console.log('errors', formik.errors) }, [])



    return (
        <>

            <Modal
                isOpen={openCounterDiscountDialog}
                placement="top"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />


                            <ModalHeader className="flex flex-col gap-1 text-center text-large font-bold">Enter percent counter discount</ModalHeader>
                            <ModalBody>
                                <Card className="max-w-full ">

                                    <CardBody className="overflow-hidden">


                                        <form className="flex flex-col gap-4" onSubmit={formik.handleSubmit}>
                                            <Input
                                                id="counter_discount"
                                                name="counter_discount"
                                                autoFocus
                                                label="Discount awarded over the counter"
                                                placeholder="Enter % discount not exceeding 20%"
                                                variant="bordered"
                                                type="number"
                                                
                                                onChange={formik.handleChange}
                                                onBlur={formik.handleBlur}
                                                defaultValue={formik.values.counter_discount}
                                                value={formik.values.counter_discount}
                                                color={formik.errors.counter_discount ? "danger" : "grey"}
                                                errorMessage={formik.errors.counter_discount}
                                            />
                                            <div className="flex gap-2 justify-end">
                                                <Button type="submit" fullWidth color="primary">
                                                    Save
                                                </Button>
                                            </div>
                                        </form>



                                    </CardBody>
                                </Card>
                            </ModalBody>
                            <ModalFooter>
                                <Button color="danger" variant="flat" onPress={() => setopenCounterDiscountDialog(false)}>
                                    Cancel
                                </Button>

                            </ModalFooter>



                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
