import { Avatar, Button, Card, CardBody, CardHeader } from '@heroui/react'
import React from 'react'
import { CardFooter } from 'reactstrap'
import { useStateContext } from '../../../contexts/ContextProvider'

export default function RequisitionEstimateCard({ item, onPress }) {
    const {currentColor}=useStateContext()
    return (
        <Card>

            <CardHeader>
                <div className='flex gap-5 items-center mx-2 justify-start w-full'>
                    <Avatar
                        isBordered
                        radius="full"
                        size="lg"
                        src={
                            item.images && item.images[0]
                                ? item.images[0].image
                                : ""
                        }
                        name={item.product_title}
                    />
                    <div>
                        <p className='text-medium font-semibold leading-none text-default-600'>{item.product_title}</p>
                        <p className="text-medium tracking-tight text-default-500">
                            {item.wholesaler_title}
                        </p>
                    </div>
                </div>

            </CardHeader>

            <CardBody className='grid grid-cols-1 '>
                <div className='grid grid-cols-1 md:grid-cols-3 md:justify-center md:items-center'>
                    <p className="text-medium tracking-tight text-default-400">
                        Average Daily Sales {item.average_sold_daily}
                    </p>
                    <p className="text-medium tracking-tight text-default-400 ">
                        Requisition Estimate: {item.required_estimate}
                    </p>
    <div className='flex justify-end'>
                <Button onPress={()=>onPress(item)} style={{background:currentColor,color:'white'}} className=''>Find Offers</Button>
                </div>
                </div>
            

            </CardBody>
          
        </Card>
    )
}
