import React, { useEffect, useRef, useState } from "react";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import useApi from "../../../hooks/useApi";
import employeesApi from "../../../api/employees/employeesApi";
import * as Yup from "yup";
import {
  createOrderItem,
  retrieveDraftCustomerOrders,
  updateOrderItems,
  removeOrderItem,
  updateOtherOrderDetails,
  deleteDraftOrder,
  updateOrderItemDiscount,
  updateOrderItemQuantity,
} from "../../../helpers/retailerHelpers";
import { SelectorIcon } from "@heroicons/react/solid";
import {
  Avatar,
  Card,
  CardFooter,
  CardHeader,
  CardBody,
  Input,
  Divider,
  Tab,
  Tabs,
  RadioGroup,
} from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomRadioItem,
  DeleteIcon,
  Loading,
  PlusIcon,
  SearchIcon,
} from "../../../components";
import { BiSolidOffer } from "react-icons/bi";
import { AiOutlineShoppingCart } from "react-icons/ai";
import { useStateContext } from "../../../contexts/ContextProvider";
import RequiredQuantityFormModal from "./RequiredQuantityFormModal";
import useScreenSize from "../../../hooks/useScreenSize";
import { ToastContainer, toast } from "react-toastify";
import paymentsApi from "../../../api/paymentsApi";
import { Button } from "@heroui/react";
import ShippingAddressModal from "./ShippingAddressModal";
import MpesaNumberFormModal from "./MpesaNumberFormModal";
import CounterDiscountFormModal from "./CounterDiscountFormModal";
import CashPaymentFormModal from "./CashPaymentFormModal";
import { formatKenyaPhoneNumber } from "../../../helpers/utils";
import customerOrdersApi from "../../../api/retailers/customerOrdersApi";
import {
  DeleteForeverTwoTone,
  DiscountTwoTone,
  Edit,
  RefreshRounded,
} from "@mui/icons-material";
import { useDispatch, useSelector } from "react-redux";
import { getRetailerReceipts } from "../../../redux/retailers/receipts/actions";
import "react-toastify/dist/ReactToastify.css";
import { CardTitle } from "reactstrap";
import { usePageVisibility } from "../../../hooks/userPageVisibility";
import retailersApi from "../../../api/retailers/retailersApi";
import { useFormik } from "formik";
import RequisitionEstimateCard from "./RequisitionEstimateCard";

function RequisitionEstimates() {
  const [selected, setSelected] = React.useState();
  const screenSize = useScreenSize();
  const { draft_id } = useParams();
  const location = useLocation()

  console.log("location", location);

  const [selectedIndent, setselectedIndent] = useState();
  const [selectedEstimateItem, setselectedEstimateItem] = useState();
  const [wholesaleOffers, setwholesaleOffers] = useState([]);

  const dispatch = useDispatch();
  const retailerReceipts = useSelector(
    (state) => state.RetailerReceipts.retailerReceipts
  );
  const loading = useSelector((state) => state.RetailerReceipts.loading);

  const [employeeId, setemployeeId] = useState();
  const [data, setdata] = useState([]);
  const [errors, setErrors] = useState([]);
  const { currentColor, successColor } = useStateContext();

  const [openShippingAddressModal, setopenShippingAddressModal] =
    useState(false);
  const [shippingDetails, setshippingDetails] = useState();

  const [openMpesaNumberModal, setopenMpesaNumberModal] = useState(false);
  const [mpesaNumber, setmpesaNumber] = useState();

  const [openCashpaymentModal, setopenCashpaymentModal] = useState(false);

  const [openCounterDiscountDialog, setopenCounterDiscountDialog] =
    useState(false);
  const [counterDiscount, setcounterDiscount] = useState();

  const [currentEmploymentDetails, setcurrentEmploymentDetails] = useState();
  const [draftCustomerOrders, setdraftCustomerOrders] = useState([]);
  const [openRequiredQuantityModal, setopenRequiredQuantityModal] =
    useState(false);
  // const [retailerReceipts, setRetailerReceipts] = useState([])
  const [quantity, setQuantity] = useState();
  const [selectedRetailerReceipt, setselectedRetailerReceipt] = useState();
  const [selectedOrderItems, setselectedOrderItems] = useState([]);
  const [draftId, setdraftId] = useState(draft_id);
  const [selectedPaymentMethod, setselectedPaymentMethod] = useState(
    selectedIndent && selectedIndent.payment_method
      ? selectedIndent.payment_method
      : ""
  );
  const [selectedDeliveryOption, setselectedDeliveryOption] = useState(
    selectedIndent && selectedIndent.delivery_method
      ? selectedIndent.delivery_method
      : ""
  );
  const [orderTotal, setorderTotal] = useState();
  const [cashbalance, setcashbalance] = useState(0);
  const [tenderedAmount, settenderedAmount] = useState();
  const [selectedOrderItem, setselectedOrderItem] = useState();
  const [retailOndent, setretailOndent] = useState(location.state.item)

  const navigate = useNavigate();
  const getDraftOrders = async () => {
    const drafts = await retrieveDraftCustomerOrders();

    console.log("retrieved drafts", drafts);

    if (drafts) {
      setdraftCustomerOrders(drafts);
    }
  };

  useEffect(() => {
    if (draft_id) setdraftId(draft_id);
  }, [draftId]);

  //Retrieve employment details
  const getCurrentEmploymentDetailsApi = useApi(
    employeesApi.employeesActionJoint
  );
  const getCurrentEmploymentDetails = async () => {
    await getCurrentEmploymentDetailsApi.request({
      action: "CurrentUserEmployment",
    });
  };

  useEffect(() => {
    if (getCurrentEmploymentDetailsApi.data) {
      if (getCurrentEmploymentDetailsApi.data.employee) {
        setemployeeId(getCurrentEmploymentDetailsApi.data.employee.id);
        setcurrentEmploymentDetails(
          getCurrentEmploymentDetailsApi.data.employee
        );
      }
    }

    console.log(
      "getCurrentEmploymentDetailsApi.data",
      getCurrentEmploymentDetailsApi.data
    );
  }, [getCurrentEmploymentDetailsApi.data]);

  useEffect(() => {
    getDraftOrders();
    getCurrentEmploymentDetails();
  }, []);

  //Set selected order
  useEffect(() => {
    if (draftCustomerOrders.length) {
      setselectedIndent(
        draftCustomerOrders.find((x) => x.draft_id === draftId)
      );
    }
  }, [draftCustomerOrders]);

  const customerOrderActionsApi = useApi(
    customerOrdersApi.customerOrdersActionAdmin
  );

  const orderEstimateApi = useApi(retailersApi.retailerOrdersStaffAction);
  const wholesaleOffersApi = useApi(retailersApi.retailerOrdersStaffAction);

  const handleFilter = (e) => {
    const search_param = e.target.value;

    if (
      orderEstimateApi.data &&
      orderEstimateApi.data.length > 0 &&
      search_param &&
      search_param !== ""
    ) {
      setdata(
        orderEstimateApi.data.filter((x) =>
          x.wholesale_receipt_title.toLowerCase().includes(search_param)
        )
      );
    } else {
      setdata(orderEstimateApi.data);
    }
  };



  useEffect(() => {
    if (retailOndent) {
      generateOrderEstimates(retailOndent.lead_time, retailOndent.order_days)
    }
  }, [retailOndent])

  const generateOrderEstimates = async (lead_time, order_days) => {
    await orderEstimateApi.request({
      action: "GenerateOrderItemEstimates",
      lead_time_days: lead_time,
      order_days: order_days,
    });
  };

  const isPageVisible = usePageVisibility();
  const timerIdRef = useRef(null);
  const [isPollingEnabled, setIsPollingEnabled] = useState(true);

  useEffect(() => {
    const pollingCallback = () => {
      // Your polling logic here
      console.log("Polling...");
      dispatch(getRetailerReceipts({ action: "GetRetailerReceipts" }));
    };

    const startPolling = () => {
      // pollingCallback(); // To immediately start fetching data
      // Polling every 10 seconds
      timerIdRef.current = setInterval(pollingCallback, 200000);
    };

    const stopPolling = () => {
      clearInterval(timerIdRef.current);
    };

    if (isPageVisible && isPollingEnabled) {
      startPolling();
    } else {
      stopPolling();
    }

    return () => {
      stopPolling();
    };
  }, [isPageVisible, isPollingEnabled]);

  const handleAddToIndent = (item) => {
    setopenRequiredQuantityModal(true);
    console.log("clicked ", item);
    setselectedOrderItem(item);
    setQuantity(selectedEstimateItem.required_estimate);
  };

  useEffect(() => {
    setdata(orderEstimateApi.data);
    setdata(orderEstimateApi.data);
    if (orderEstimateApi.data && orderEstimateApi.data.length) {
      setdata(orderEstimateApi.data);
    }
  }, [orderEstimateApi.data]);



  const handleRetrieveWholesaleOffers = async (item) => {
    setselectedEstimateItem(item);
    setwholesaleOffers([]);
    wholesaleOffersApi.request({
      action: "RetrieveProductWholesaleOffers",
      product: item.product,
    });
  };

  useEffect(() => {
    if (wholesaleOffersApi.data && wholesaleOffersApi.data.length) {
      setwholesaleOffers(wholesaleOffersApi.data);
    }

    console.log("wholesaleOffersApi.data", wholesaleOffersApi.data);
  }, [wholesaleOffersApi.data]);

  return (
    <div>
      {screenSize.width < 768 ? (
        <div>
          <Card className="max-w-full rounded-sm">
            <ToastContainer position="bottom-center" theme="colored" />
            <CardBody className="overflow-hidden">
              <Tabs
                fullWidth
                size="md"
                aria-label="Tabs form"
                selectedKey={selected}
                onSelectionChange={setSelected}
              >
                <Tab key="products" title="Products">
                  <div className="max-h-[720px] bg-gray-100 overflow-y-scroll">
                    <h1 className="text-large font-bold text-center">
                      Order Estimates
                    </h1>
                    {customerOrderActionsApi.loading ? (
                      <Loading loading={customerOrderActionsApi.loading} />
                    ) : (
                      <div>
                        <Card className="max-w-full mx-1 md:mx-5 my-1">
                          <CardBody>
                            <Input
                              label="Search"
                              isClearable
                              radius="lg"
                              onChange={(e) => handleFilter(e)}
                              classNames={{
                                label: "text-black/50 dark:text-white/90",
                                input: [
                                  "bg-transparent",
                                  "text-black/90 dark:text-white/90",
                                  "placeholder:text-default-700/50 dark:placeholder:text-white/60",
                                ],
                                innerWrapper: "bg-transparent",
                                inputWrapper: [
                                  "shadow-xl",
                                  "bg-default-200/50",
                                  "dark:bg-default/60",
                                  "backdrop-blur-xl",
                                  "backdrop-saturate-200",
                                  "hover:bg-default-200/70",
                                  "dark:hover:bg-default/70",
                                  "group-data-[focused=true]:bg-default-200/50",
                                  "dark:group-data-[focused=true]:bg-default/60",
                                  "!cursor-text",
                                ],
                              }}
                              placeholder="Type to search..."
                              startContent={
                                <SearchIcon className="text-black/50 dark:text-white/90 text-slate-400 pointer-events-none flex-shrink-0" />
                              }
                            />
                          </CardBody>
                          </Card>

                      </div>
                    )}
                    {data &&
                      data.length > 0 &&
                      data.map((item) => (
                        <RequisitionEstimateCard item={item} onPress={() =>
                          handleRetrieveWholesaleOffers(item)} />
                      ))}
                  </div>
                </Tab>
                <Tab key="cart" title="Customer Order">
                  <div className="max-h-[720px] bg-gray-100 overflow-y-scroll my-2">
                    <h1 className="text-large font-bold text-center">
                      Wholesale Offers
                    </h1>

                    {wholesaleOffers.map((item) => (
                      <Card
                        onClick={() => handleAddToIndent(item)}
                        className="max-w-full mx-1 md:mx-5 my-2 cursor-pointer"
                      >
                        <CardHeader className="justify-between md:flex-row">
                          <div className="flex gap-5 items-center">
                            <Avatar
                              className="w-20 h-20 text-large"
                              radius="sm"
                              size="lg"
                              src={
                                item.images && item.images[0]
                                  ? item.images[0].image
                                  : ""
                              }
                              name={item.product_title}
                            />
                            <div className="flex flex-col gap-1 items-start justify-center">
                              <h4 className="text-medium font-semibold leading-none text-default-600">
                                {item.product_title}
                              </h4>

                              <p className="text-medium tracking-tight text-default-400">
                                {item.wholesaler_title}
                              </p>
                              <h5 className="text-medium tracking-tight text-default-400">
                                Average Daily Sales {item.average_sold_daily}
                              </h5>
                              <h6 className="text-medium tracking-tight text-default-400">
                                Estimate to Purchase: {item.required_estimate}
                              </h6>
                            </div>
                          </div>
                          <BiSolidOffer
                            onClick={() => handleRetrieveWholesaleOffers(item)}
                            className="cursor-pointer hover:resize-x"
                            size={24}
                            color={
                              selectedIndent &&
                              selectedIndent.orderItems &&
                              selectedIndent.orderItems.length &&
                              selectedIndent.orderItems &&
                              selectedIndent.orderItems.length &&
                              selectedIndent.orderItems.filter(
                                (x) => x.retailer_receipt === item.id
                              ).length > 0
                                ? successColor
                                : currentColor
                            }
                          />
                        </CardHeader>
                      </Card>
                    ))}

                    {openCashpaymentModal && (
                      <CashPaymentFormModal
                        openEditModal={openCashpaymentModal}
                        setopenEditModal={setopenCashpaymentModal}
                        orderTotal={orderTotal}
                        tenderedAmount={tenderedAmount}
                        setTenderedAmount={settenderedAmount}
                        cashbalance={cashbalance}
                        setcashbalance={setcashbalance}
                      />
                    )}
                    {openMpesaNumberModal && (
                      <MpesaNumberFormModal
                        openEditModal={openMpesaNumberModal}
                        setopenEditModal={setopenMpesaNumberModal}
                        mpesaNumber={mpesaNumber}
                        setmpesaNumber={setmpesaNumber}
                      />
                    )}

                    {openRequiredQuantityModal && (
                      <RequiredQuantityFormModal
                        selectedEstimateItem={selectedEstimateItem}
                        openEditModal={openRequiredQuantityModal}
                        selectedOrderItem={selectedOrderItem}
                        setopenEditModal={setopenRequiredQuantityModal}
                        quantity={quantity}
                        setQuantity={setQuantity}
                      />
                    )}
                  </div>
                </Tab>
              </Tabs>
            </CardBody>
          </Card>
        </div>
      ) : (
        <div className="grid md:grid-cols-2 gap-6">
          {loading ? (
            <Loading loading={loading} />
          ) : (
            <div className="max-h-[720px] bg-gray-100 overflow-y-scroll">
              <ToastContainer position="bottom-center" theme="colored" />
              <h1 className="text-large font-bold text-center">
                Order Estimates
                  </h1>


              {data &&
                data.length > 0 &&
                    data.map((item) => (
                      <RequisitionEstimateCard item={item} onPress={() =>
                        handleRetrieveWholesaleOffers(item)} />
                ))}

              {openRequiredQuantityModal && (
                <RequiredQuantityFormModal
                  selectedEstimateItem={selectedEstimateItem}
                  openEditModal={openRequiredQuantityModal}
                  selectedOrderItem={selectedOrderItem}
                  setopenEditModal={setopenRequiredQuantityModal}
                  quantity={quantity}
                  setQuantity={setQuantity}
                />
              )}
            </div>
          )}
          <div className="max-h-[720px] bg-gray-100 overflow-y-scroll">
            <Card className="max-w-full mx-1 md:mx-5 my-1 rounded-sm">
              <CardHeader>
                <CardTitle className="font-bold text-lg">
                  Wholesale Offers
                </CardTitle>
              </CardHeader>
            </Card>
            {wholesaleOffers &&
              wholesaleOffers.map((item) => (
                <Card
                  onClick={() => handleAddToIndent(item)}
                  className="max-w-full mx-1 md:mx-5 my-2 cursor-pointer"
                >
                  <CardHeader className="justify-between md:flex-row">
                    <div className="flex gap-5 items-center">
                      <Avatar
                        className="w-20 h-20 text-large"
                        radius="sm"
                        size="lg"
                        src={
                          item.images && item.images[0]
                            ? item.images[0].image
                            : ""
                        }
                        name={item.product_title}
                      />
                      <div className="flex flex-col gap-1 items-start justify-center">
                        <h4 className="text-medium font-semibold leading-none text-default-600">
                          {item.product_title}
                        </h4>

                        <p className="text-medium tracking-tight text-default-400">
                          {item.entity_title}
                        </p>
                        <h5 className="text-medium tracking-tight text-default-400">
                          Pack Price: KES{item.pack_selling_price}
                        </h5>
                        <h6 className="text-medium tracking-tight text-default-400">
                          Price Discount:{" "}
                          {item.wholesaler_price_discount
                            ? item.wholesaler_price_discount.title
                            : "N/A"}
                        </h6>
                        <p>Quantity Discounts</p>
                        {item.wholesaler_quantity_discounts &&
                        item.wholesaler_quantity_discounts.length ? (
                          <div>
                            {item.wholesaler_quantity_discounts.map((x) => (
                              <p>{x.title}</p>
                            ))}
                          </div>
                        ) : (
                          <div>
                            <p>N/A</p>
                          </div>
                        )}
                      </div>
                    </div>
                    <AiOutlineShoppingCart
                      onClick={() => handleAddToIndent(item)}
                      className="cursor-pointer hover:resize-x"
                      size={24}
                      color={
                        selectedIndent &&
                        selectedIndent.orderItems &&
                        selectedIndent.orderItems.length &&
                        selectedIndent.orderItems &&
                        selectedIndent.orderItems.length &&
                        selectedIndent.orderItems.filter(
                          (x) => x.retailer_receipt === item.id
                        ).length > 0
                          ? successColor
                          : currentColor
                      }
                    />
                  </CardHeader>
                </Card>
              ))}
          </div>
        </div>
      )}
    </div>
  );
}

export default RequisitionEstimates;
