import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import {
  Modal,
  ModalContent,
  ModalHeader,
  ModalBody,
  ModalFooter,
  Button,
  useDisclosure,
  Checkbox,
  Tabs,
  Tab,
  Input,
  Link,
  Card,
  CardBody,
  CardHeader,
  user,
} from "@heroui/react";
import { useFormik } from "formik";

import { ToastContainer, toast } from "react-toastify";
import { CustomForm, CustomFormItem, CustomInput } from "../../../components";
import { useStateContext } from "../../../contexts/ContextProvider";
import { createIndentItem } from "../../../helpers/retailerHelpers";
import useApi from "../../../hooks/useApi";
import retailersApi from "../../../api/retailers/retailersApi";

export default function RequiredQuantityFormModal({
  openEditModal,
  setopenEditModal,
  quantity,
  setQuantity,
  selectedOrderItem,
  selectedEstimateItem,
}) {
  const formik = useFormik({
    initialValues: {
      required_quantity: quantity,
    },

    validationSchema: Yup.object({
      required_quantity: Yup.number().min(1).required().label("Quantity"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      setQuantity(values.required_quantity);
      setopenEditModal(false);
      const data = {
        action: "CreateRetailerIndentItem",
        wholesale_receipt: selectedOrderItem.id,
        required_quantity: values.required_quantity,
        indenting_criteria: "OUT_OF_STOCK",
        retailer_indent: selectedEstimateItem.retailer_indent,
      };

      createIndentItem(data);
    },
  });

  const indentItemApi = useApi(retailersApi.retailerOrdersStaffAction);
  const createIndentItem = async (data) => {
    await indentItemApi.request(data);
  };

  useEffect(() => {
    console.log("indentItemApi.data", indentItemApi.data);
  }, [indentItemApi.data]);

  useEffect(() => {
    console.log("errors", formik.errors);
  }, []);

  const { currentColor } = useStateContext();

  return (
    <>
      <Modal isOpen={openEditModal} placement="top">
        <ModalContent>
          {(onClose) => (
            <>
              <ToastContainer position="bottom-center" theme="colored" />

              <ModalHeader className="flex flex-col gap-1 text-center text-large font-bold">
                {selectedOrderItem
                  ? selectedOrderItem.product_title
                  : "Enter quantity"}
              </ModalHeader>
              <ModalBody>
                <Card className="max-w-full ">
                  <CardBody className="overflow-hidden">
                    <CustomForm
                      layout="horizontal"
                      handleFinish={formik.handleSubmit}
                      className=" flex flex-col justify-center items-center w-full my-7"
                    >
                      <div className="items-center justify-center flex-row w-full">
                        <CustomFormItem
                          touched={formik.touched.required_quantity}
                          error={formik.errors.required_quantity}
                        >
                          <CustomInput
                            id="required_quantity"
                            name="required_quantity"
                            onChange={formik.handleChange}
                            placeholder="Confirm or change  quantity"
                            size="large"
                            type="number"
                            value={formik.values.required_quantity}
                            label="Enter required quantity"
                          />
                        </CustomFormItem>

                        <div className="w-full items-center mt-2">
                          <Button
                            style={{
                              background: currentColor,
                              color: "white",
                            }}
                            className="w-full rounded-md self-center"
                            color="primary"
                            type="submit"
                          >
                            Save
                          </Button>
                        </div>
                      </div>
                    </CustomForm>
                  </CardBody>
                </Card>
              </ModalBody>
              <ModalFooter>
                <Button
                  color="danger"
                  variant="flat"
                  onPress={() => setopenEditModal(false)}
                >
                  Cancel
                </Button>
              </ModalFooter>
            </>
          )}
        </ModalContent>
      </Modal>
    </>
  );
}
