import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Input, Link, Textarea } from "@heroui/react";
import { useFormik } from "formik";
import { ToastContainer, toast } from "react-toastify";




export default function CashPaymentFormModal({ openEditModal, setopenEditModal, orderTotal, tenderedAmount, setTenderedAmount, cashbalance, setcashbalance }) {
    // const { isOpen, onOpen, onOpenChange } = useDisclosure();
    const [errors, setErrors] = useState();
    console.log("Order total",orderTotal);


    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    const formik = useFormik({
        initialValues: {
            tendered_amount: '',
            order_total: orderTotal ? orderTotal : '',

        },

        validationSchema: Yup.object({
            order_total: Yup.number().min(0)
                .required().label('Shipping cost'),

        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action

            console.log('VALZ', values)
            setErrors([])
            setTenderedAmount(values.tendered_amount)
            setcashbalance(parseFloat(tenderedAmount) - parseFloat(orderTotal))
            setopenEditModal(false)


        },
    });

    const handleAmountChange=(e)=>{
        console.log("amount..",e)
        formik.setFieldValue("tendered_amount",e.target.value)
     
            setcashbalance(parseFloat(e.target.value)-parseFloat(orderTotal))
        
    }




    return (
        <>

            <Modal
                isOpen={openEditModal}
                placement="center"
            >
                <ModalContent>

                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />

                            <form className="items-center grid grid-cols-1"
                                onSubmit={formik.handleSubmit}
                            > <ModalHeader className="flex flex-col gap-1  items-center" onClick={() => setopenEditModal(false)}>Confirm Cash Payment</ModalHeader>
                                <ModalBody className="overflow-y-scroll">

                                    <Input
                                        id="tendered_amount"
                                        name="tendered_amount"
                                        autoFocus
                                        label="Recipient name"
                                        placeholder="Enter contact person name"
                                        variant="bordered"
                                        type="text"
                                        onChange={(e)=>handleAmountChange(e)}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.tendered_amount}
                                        value={formik.values.tendered_amount}
                                        color={formik.errors.tendered_amount ? "danger" : "grey"}
                                        errorMessage={formik.errors.tendered_amount}
                                    />
                                    <Input
                                        id="order_total"
                                        name="order_total"
                                        autoFocus
                                        isDisabled
                                        placeholder="Enter contact person name"
                                        variant="bordered"
                                        type="text"
                                        onChange={formik.handleChange}
                                        onBlur={formik.handleBlur}
                                        defaultValue={formik.values.order_total}
                                        value={formik.values.order_total}
                                        color={formik.errors.order_total ? "danger" : "grey"}
                                        errorMessage={formik.errors.order_total}
                                    />
                                    <div>
                                        <h1 className="text-center text-default-500 font-bold text-medium">Customer Change</h1>
                                        <h1 className="text-center font-bold text-large">{parseFloat(cashbalance).toFixed(2)}</h1>
                                    </div>

                                </ModalBody>
                                <ModalFooter>


                                    <Button color="danger" variant="flat" onPress={() => setopenEditModal(false)}>
                                        Cancel
                                    </Button>
                                    <Button color="primary" type="submit" onPress={onClose}>
                                        Confirm
                                    </Button>
                                </ModalFooter>

                            </form>


                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
